// ---- from Code/GameEngine/Source/Common/Energy_getEnergySupplyRatio.cpp

float Energy::getEnergySupplyRatio() const
{
	int consumption = m_energyConsumption;
	if (consumption == 0)
		return 1.0f;
	return (float)m_energyProduction / (float)consumption;
}

// ---- from Code/GameEngine/Source/Common/Rva004DF17FCompare.cpp

bool Rva004DF17F::rva004DF17F() const
{
	return m_04 >= m_08;
}

// ---- from Code/GameEngine/Source/Common/RTS/EnergyAdjustPower.cpp

// ?adjustPower@Energy@@QAEXH_N@Z
void Energy::adjustPower(int powerDelta, bool adding)
{
	if (powerDelta == 0)
		return;

	if (powerDelta > 0)
	{
		if (adding)
			addProduction(powerDelta);
		else
			addProduction(-powerDelta);
	}
	else
	{
		if (adding)
			addConsumption(-powerDelta);
		else
			addConsumption(powerDelta);
	}
}

