void Energy::objectEnteringInfluence(Object *obj)
{
	if (!obj)
		return;
	Rva004DF207Outer *o = (Rva004DF207Outer *)obj;
	int energy = o->m_ptr->m_val;
	if (energy < 0)
		rva004DF1AF(-energy);
	else if (energy > 0)
		rva004DF18D(energy);
}

void Energy::objectLeavingInfluence(Object *obj)
{
	if (!obj)
		return;
	Rva004DF231Outer *o = (Rva004DF231Outer *)obj;
	int energy = o->m_ptr->m_val;
	if (energy < 0)
		rva004DF1AF(energy);
	else if (energy > 0)
		rva004DF18D(-energy);
}

